data.solution:
def summarize_hierarchy(hierarchy):
    outer = 0
    holes = 0
    for entry in hierarchy:
        parent = entry[3]
        if parent == -1:
            outer += 1
        else:
            holes += 1
    return {"outer": outer, "holes": holes}
